CREATE SCHEMA IF NOT EXISTS random_stranger;
REVOKE ALL ON SCHEMA random_stranger FROM PUBLIC, anon, authenticated;

 CREATE TABLE IF NOT EXISTS random_stranger.users(id TEXT PRIMARY KEY,provider TEXT,subject TEXT,email TEXT,name TEXT,status TEXT DEFAULT 'active',UNIQUE(provider,subject));
 CREATE TABLE IF NOT EXISTS random_stranger.profiles(user_id TEXT PRIMARY KEY REFERENCES random_stranger.users(id) ON DELETE CASCADE,data TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS random_stranger.sessions(hash TEXT PRIMARY KEY,user_id TEXT REFERENCES random_stranger.users(id) ON DELETE CASCADE,expires BIGINT);
 CREATE TABLE IF NOT EXISTS random_stranger.attempts(hash TEXT PRIMARY KEY,data TEXT,expires BIGINT);
 CREATE TABLE IF NOT EXISTS random_stranger.handoffs(hash TEXT PRIMARY KEY,user_id TEXT REFERENCES random_stranger.users(id) ON DELETE CASCADE,challenge TEXT,expires BIGINT);
 CREATE TABLE IF NOT EXISTS random_stranger.appointments(id TEXT PRIMARY KEY,a TEXT REFERENCES random_stranger.users(id) ON DELETE SET NULL,b TEXT REFERENCES random_stranger.users(id) ON DELETE SET NULL,start BIGINT,"end" BIGINT,venue TEXT,status TEXT DEFAULT 'proposed',confirm_a INTEGER DEFAULT 0,confirm_b INTEGER DEFAULT 0,check_a INTEGER DEFAULT 0,check_b INTEGER DEFAULT 0,decision_a INTEGER,decision_b INTEGER,alias_a TEXT NOT NULL DEFAULT '',alias_b TEXT NOT NULL DEFAULT '');
 CREATE TABLE IF NOT EXISTS random_stranger.strikes(id TEXT PRIMARY KEY,user_id TEXT REFERENCES random_stranger.users(id) ON DELETE CASCADE,appointment_id TEXT REFERENCES random_stranger.appointments(id) ON DELETE CASCADE,reason TEXT,created BIGINT,UNIQUE(user_id,appointment_id));
 CREATE TABLE IF NOT EXISTS random_stranger.blocks(a TEXT REFERENCES random_stranger.users(id) ON DELETE CASCADE,b TEXT REFERENCES random_stranger.users(id) ON DELETE CASCADE,PRIMARY KEY(a,b));
 CREATE TABLE IF NOT EXISTS random_stranger.reports(id TEXT PRIMARY KEY,appointment_id TEXT REFERENCES random_stranger.appointments(id) ON DELETE CASCADE,reporter TEXT REFERENCES random_stranger.users(id) ON DELETE CASCADE,target TEXT REFERENCES random_stranger.users(id) ON DELETE CASCADE,reason TEXT,appeal TEXT,status TEXT DEFAULT 'pending',created BIGINT,kind TEXT NOT NULL DEFAULT 'absence',UNIQUE(appointment_id,reporter));
 CREATE TABLE IF NOT EXISTS random_stranger.profile_reviews(user_id TEXT PRIMARY KEY REFERENCES random_stranger.users(id) ON DELETE CASCADE,content_hash TEXT,status TEXT,approved_data TEXT);
 CREATE TABLE IF NOT EXISTS random_stranger.content_reports(id TEXT PRIMARY KEY,appointment_id TEXT REFERENCES random_stranger.appointments(id) ON DELETE CASCADE,reporter TEXT REFERENCES random_stranger.users(id) ON DELETE CASCADE,target TEXT REFERENCES random_stranger.users(id) ON DELETE CASCADE,reason TEXT,status TEXT DEFAULT 'pending',created BIGINT,UNIQUE(appointment_id,reporter));
 CREATE TABLE IF NOT EXISTS random_stranger.exclusions(identity_hash TEXT PRIMARY KEY,created BIGINT);
 CREATE TABLE IF NOT EXISTS random_stranger.live_positions(user_id TEXT REFERENCES random_stranger.users(id) ON DELETE CASCADE,appointment_id TEXT REFERENCES random_stranger.appointments(id) ON DELETE CASCADE,lat DOUBLE PRECISION,lon DOUBLE PRECISION,expires BIGINT,PRIMARY KEY(user_id,appointment_id));
ALTER TABLE random_stranger.users ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON random_stranger.users FROM PUBLIC, anon, authenticated;
