CREATE INDEX IF NOT EXISTS appointments_a_start ON random_stranger.appointments(a,start);
CREATE INDEX IF NOT EXISTS appointments_b_start ON random_stranger.appointments(b,start);
CREATE INDEX IF NOT EXISTS sessions_user ON random_stranger.sessions(user_id);
